INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4149, 'Musa na paka', 'sw', 'Musa anamuokota paka akiwa njiani kutoka shuleni kisha anamnyanyasa. Baadaye Nível: First paragraphs. Ilustração: Tawanda Mhandu.', 'http://africanstorybook.org/illustrations/covers/22352.png', NULL, 204, 25, 20, 'asp-22352', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4150, 'Tomu omutunzi w''amenvu', 'lg', 'A man goes against community norms and brings his bananas to sell at the market. Nível: First sentences. Ilustração: Atilabachew Reda.', 'http://africanstorybook.org/illustrations/covers/22354.png', NULL, 1264, 25, 20, 'asp-22354', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4151, 'Namu se fiets', 'afrikaans', 'N Apie ry weg met Namu se fiets. Lees verder. Nível: First sentences. Ilustração: Salim Kasamba.', 'http://africanstorybook.org/illustrations/covers/22356.png', NULL, 1059, 25, 20, 'asp-22356', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4152, 'The boy who ran away', 'en', 'This story deals with the emotions in a family when someone does something wrong. Nível: First sentences. Ilustração: Megan  Barry.', 'http://africanstorybook.org/illustrations/covers/22357.png', NULL, 788, 25, 20, 'asp-22357', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4153, 'Inyanga Ne Kepisi', 'xh', 'Nkwenkwana ithile iphiwa ikepisi eluhlaza ngumama wayo. Suke umoya uyivuthuze ikepisi iyokuwela emthini. Ebusuku kuthi gqi omnye umntu enxibe le kepisi Nível: First words. Ilustração: Angie & Upesh.', 'http://africanstorybook.org/illustrations/covers/2236.png', NULL, 1017, 25, 20, 'asp-2236', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4154, 'በጣም ረጅም ሰውዬ', 'am', 'በዚህ ታሪክ ውስጥ የምናገኘው ሰውዬ በጣም ረጅም በመሆኑ በአካባቢው ያለው ነገር ሁሉ በጣም ትንሽ ወይም በጣም አጭር ሆኖበታል፡፡ እንደሱው ትላልቅ የሆኑ ነገሮችን በመስራት ለዚህ ችግሩ መፍትሔ ይሰጠዋል፡፡ Nível: First words. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/22362.png', NULL, 1091, 25, 20, 'asp-22362', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4155, 'የትምህርት ቤት ልብሶች', 'am', 'ትምህርት ቤት ተመልሼ ልገባ ስለሆነ ሁሉንም የትምህርት ቤት ልብሶቼን መለካት አለብኝ፡፡ Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/22363.png', NULL, 1091, 25, 20, 'asp-22363', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4156, 'ፍየል፣ ዉሻና ላም', 'am', 'ፍየል፣ ዉሻና ላም በዚህች ቃላት-አልባ ተረት ምን ዓይነት ጸባይ ያሳያሉ? Nível: First words. Ilustração: Marleen Visser.', 'http://africanstorybook.org/illustrations/covers/22365.png', NULL, 1091, 25, 20, 'asp-22365', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4157, 'Gayala ashee ɩkuruci', 'anii', 'This tale explains why pigs have flat noses. What else does the story teach us? Nível: First paragraphs. Ilustração: Little Zebra Books and Laura Libertore.', 'http://africanstorybook.org/illustrations/covers/22375.png', NULL, 1315, 25, 20, 'asp-22375', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4158, 'Omusaadha Kalimagezi', 'lusoga', 'Yaliyo omusaadha ni baghala be musanvu. Baali ba mpisa inho. Yaayenda okubafumbiza. Aye nga buli musaadha ku kyalo abeeyendeza. Yakola atya? Nível: First paragraphs. Ilustração: Wiehan de Jager, Catherine Groenewald, Natalie Propa, Manyeka Arts Trust, Brian Wambi, Steven McKimmie and Jano Strydom.', 'http://africanstorybook.org/illustrations/covers/22377.png', NULL, 1316, 25, 20, 'asp-22377', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4159, 'Andiswa omusathi owomupira', 'lukhonzo', 'Andiswa anzire erisatha omupira nekithongole ekyerithendekero Nível: First sentences. Ilustração: Eden Daniels.', 'http://africanstorybook.org/illustrations/covers/22378.png', NULL, 1317, 25, 20, 'asp-22378', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4160, 'Esyambene esiwethe amenge', 'lukhonzo', 'Olhughano luno lhukakanaya okwa mulhume oyowabya awithe esyambene siwe ibiri esyo abya ayikethere kutsibu kandi abya isangalengekania ati syanganalya emiriki yiwe. Nível: First sentences. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/22379.png', NULL, 1317, 25, 20, 'asp-22379', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4161, 'Kungabya……', 'lukhonzo', 'Olhughano lhuhambangene okwa ekyabanabalere bangakolire kubabya……. Nível: First sentences. Ilustração: Wiehan de Jager, Cathy Feek, Rebecca Riley, Marleen Visser, Catherine Groenewald, Jano Strydom, Alice Toich, Karen Lilje, Natalie Propa and Rob Owen.', 'http://africanstorybook.org/illustrations/covers/22380.png', NULL, 1317, 25, 20, 'asp-22380', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4162, 'Ngendikolesya''kyi omwangenda?', 'lukhonzo', 'Omwana mwalengekania olhughendo nikwa akayibulaya nimubere wahayi omubuya owerighendesya. Nível: First sentences. Ilustração: Sue Kramer, Catherine Groenewald, Marion Drew, Louwrisa Blaauw, Rob Owen, Vusi Malindi, Jesse Breytenbach, Natalie Propa, Wiehan de Jager and Mango Tree.', 'http://africanstorybook.org/illustrations/covers/22381.png', NULL, 1317, 25, 20, 'asp-22381', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4163, 'Timonjero akiba', 'lukhonzo', 'Olhughano luhambangene okwa muyisiki oyukiba esyombulho nikwa aghule esyopipi. Nível: First words. Ilustração: Melany Pietersen, Michael Omadi and Selina Masego Morulane.', 'http://africanstorybook.org/illustrations/covers/22382.png', NULL, 1317, 25, 20, 'asp-22382', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4164, 'Daisy oweriswekerya', 'lukhonzo', 'Okwakalima kake Daisy kwahimbire Nível: First paragraphs. Ilustração: Siya Masuku.', 'http://africanstorybook.org/illustrations/covers/22383.png', NULL, 1317, 25, 20, 'asp-22383', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4165, 'Ekyalekire ekikere ikyathabya  kibuya', 'lukhonzo', 'Ekikere kyanganabere kibuya ngekihangalha kukyahulikirira! Nível: First sentences. Ilustração: Hélder de Paz Alexandre.', 'http://africanstorybook.org/illustrations/covers/22384.png', NULL, 1317, 25, 20, 'asp-22384', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4166, 'Omurundi owerimbere erighendera  omwamotoka', 'lukhonzo', 'Emotoka eyaghenda e Mbale. Omurundi owerimbere erighendera  omwamotoka. Nível: First sentences. Ilustração: Catherine Groenewald, Cathy Feek, Marion Drew, Mango Tree, Silva Afonso, Paleng Children’s Centre, Elgon, rice and Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/22385.png', NULL, 1317, 25, 20, 'asp-22385', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4167, 'Wangoko na Wakinyanyangolho', 'lukhonzo', 'Wangoko na wakinyanyangolho bawithe omukaghu owembaghane. Kiro kighuma wangoko mwayibulhabulha ahabwerisingwa nikwa akole ekindu ekyobukiru. Nível: First words. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/22387.png', NULL, 1317, 25, 20, 'asp-22387', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4168, 'አናንሲና ጥበብ', 'am', 'የሰማይ አምላክ ለሸረሪቱ ለአናንሲ አንድ ገንቦ ሙሉ ጥበብ ሊሰጠው ይወስናል፡፡ ገንቦው ውስጥ ያለውን እውቀት ሁሉ አይቶ በጣም ስለተደሰተ እውቀትን ለራሱ ብቻ ለማድረግ በመፈለግ ዛፍ ላይ ሊደብቀው ፈለገ፡፡ የእድል ነገር ሆኖ ገንቦው ይወድቅና ይሰበራል፡፡ Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/22388.png', NULL, 1091, 25, 20, 'asp-22388', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4169, 'ምን እየሰራህ ነው?', 'am', 'በአሁን ጊዜ ግሶች በተዋቀሩ አጫጭር አረፍተነገሮች የተቀመመች ተረት እነሆ! Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/22389.png', NULL, 1091, 25, 20, 'asp-22389', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4170, 'ድመቴ የታለች?', 'am', 'ድመቴ ጠፍታብኛለች፡፡ ወደሱ አካባቢ ትታያችኋለች እንዴ? ይህ ተረት በአጫጭር አረፍተ ነገሮች የተዋቀረ ልህጻናት የሚስማማ ተረት ነው፡፡ መልካም ንባብ፡፡ Nível: First words. Ilustração: Bronwen Heath.', 'http://africanstorybook.org/illustrations/covers/22390.png', NULL, 1091, 25, 20, 'asp-22390', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4171, 'ውሣኔ', 'am', 'በአንዲት መንደር የሚኖር አንድ ማህበረሰብ ሕይወቱን የሚቀይር ውሣኔ ያሳልፋል፡፡ እስኪ ስለዚህ ውሣኔያቸው አብረን እናንብብ፡፡ Nível: First paragraphs. Ilustração: Vusi Malindi.', 'http://africanstorybook.org/illustrations/covers/22401.png', NULL, 1091, 25, 20, 'asp-22401', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4172, 'ስሜቶች', 'am', 'ስለ ልዩ ልዩ ሰዎችና ነገሮች ምን እንደሚሰማን እናንብብ፡፡ ልጆች እናንተ ስለጓደኞቻችሁም ሆነ በአቅራቢያችሁ ስላሉ ነገሮች ምን ይሰማችኋል? Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/22402.png', NULL, 1091, 25, 20, 'asp-22402', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4173, 'ሲምበግዊሬ', 'am', 'የሲምበግዊሬ እናት ከሞተች በኋላ ልጅቱና አባቷ ሁሉንም ነገር አብረው ይሰሩ ጀመር፡፡ አባትዮውም አዲስ ሚስት ለማግባት እስከፈለገበት ጊዜ ድረስም ደስተኞች ነበሩ፡፡ ሴትዮዋ ልጅቱ Nível: Read aloud. Ilustração: Benjamin Mitchley.', 'http://africanstorybook.org/illustrations/covers/22403.png', NULL, 1091, 25, 20, 'asp-22403', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4174, 'ኖዚቤሌና ሦስቱ ጸጉሮች', 'am', 'ሦስት ልጃገረዶች በአንድ ሞቃት ቀን እንጨት እየሰበሩ ነው፡፡ ዋና ለመዋኘት ወደ ወንዝ ወርደው ዋኝተው ሲጨርሱ መሸባቸው፡፡ ወደ ቤታቸውም መሮጥ ግድ ሆነባቸው፡፡ መንገድም ላይ ኖዚቤሌ ዶቃዋን እንደረሳችው አስታወሰች፡፡ ብቻዋንም ወደ ወንዙ ተመለሰች፡፡ከዚያች ደቂቃም በኋላ ጉዞዋ ያልተጠበቀ አቅጣጫ ይይዛል፡፡ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/22405.png', NULL, 1091, 25, 20, 'asp-22405', 'cc-by', 0, NULL);
